// Simplified C parser
//
//     No typedef support
//     No pre-precessor directive support
//     No multi-line comment support
//     Incomplete string literal
//     Incomplete number literal



let TokenMacher = function(){
    this.result = false; this.match = null; this.rest = null;
}
TokenMacher.prototype.regexp = function(target, pat) {

    // this.result  = target.match(pat);
    this.result  = pat.exec(target);
    if (this.result !== null)
    {
     // const ia = result.index;
     // const ib = ia + result[0].length;
     const ib = this.result.index + this.result[0].length;
     // const a = target.substring(0,ia);
     // const b = target.substring(ia,ib);
     // const c = target.substring(ib);
     // return [a,b,c];

     this.match = target.substring(0,ib);
     this.rest = target.substring(ib);
     this.result = true;
    }
    else
    {
        this.result = false;
    }

    return this.result;
};
TokenMacher.prototype.str = function(target, pat) {
    if (target.length < pat.length) { this.result = false; }
    else
    {
        let target_head = target.substring(0,pat.length);
        if (target_head == pat)
        {
            this.match = target_head;
            this.rest = target.substring(pat.length);
            this.result = true;
        }
        else { this.result = false }
    }
    return this.result;
}
TokenMacher.prototype.str_list= function(target, pat_list) {
    for (let pat of pat_list)
    {
        if (this.str(target, pat)) { return true; }
    }
    return false;
}




///////////////////////////////////////////////////////////////

// 簡易版の C パーサ
//     プリプロセッサ指令は無視
//     複数行コメントは未対応
//     typedef 未対応
//     文字列即値定数は不完全
//     その他の即値定数(整数、実数など)も不完全

let Tokenizer2 = function(str)
{
    this.str_orig = str.slice();
    this.str_rest = str.slice();
    this.read_next_token();

    //     my $class = shift;
    //     my ($str) = @_;

    //     my $self = {str_rest => $str, str_orig => $str};
    //     # my $self = {token_list => [@_], pos=> 0};

    //     bless $self,$class;
    //     $self->read_next_token();
    //     return $self

};

Tokenizer2.prototype.reset = function() {
    this.str_rest = this.str_orig.slice(); this.read_next_token();
};

// Terminal Symbols:
//    ! % & ( ) * + , - . / : ; < = > ? [ ] ^ { | } ~

// PTR_OP NE_OP AND_OP OR_OP INC_OP DEC_OP LEFT_OP RIGHT_OP EQ_OP LE_OP GE_OP

// ELIPSIS

// ADD_ASSIGN SUB_ASSIGN MUL_ASSIGN DIV_ASSIGN MOD_ASSIGN
// AND_ASSIGN OR_ASSIGN XOR_ASSIGN
// 
// LEFT_ASSIGN RIGHT_ASSIGN
// 
// 
// AUTO BREAK CASE CHAR CONST CONTINUE
// DEFAULT DO DOUBLE ELSE ENUM EXTERN FLOAT FOR
// GOTO IF INT LONG REGISTER RETURN SHORT SIGNED
// SIZEOF STATIC STRUCT SWITCH TYPEDEF TYPE_NAME
// UNION UNSIGNED VOID VOLATILE WHILE
// 
// EOF IDENTIFIER STRING_LITERAL CONSTANT
// 
//     EXTERN_STM STM_DEF

Tokenizer2.prototype.op_1_list = '! % & ( ) * + , - . / : ; < = > ? [ ] ^ { | } ~'.split(/\s+/);

Tokenizer2.op_2_3_name =
{'->' : 'PTR_OP', '!=' : 'NE_OP', '&&' : 'AND_OP', '||' : 'OR_OP',
'++' : 'INC_OP', '--' : 'DEC_OP', '<<' : 'LEFT_OP', '>>' : 'RIGHT_OP',
'==' : 'EQ_OP', '<=' : 'LE_OP', '>=' : 'GE_OP',
'+=' : 'ADD_ASSIGN', '-=' : 'SUB_ASSIGN',
'*=' : 'MUL_ASSIGN', '/=' : 'DIV_ASSIGN', '%=' : 'MOD_ASSIGN',
'&=' : 'AND_ASSIGN', '|=' : 'OR_ASSIGN', '^=' : 'XOR_ASSIGN',
'...' : 'ELIPSIS', '<<=' : 'LEFT_ASSIGN', '>>=' : 'RIGHT_ASSIGN' };

Tokenizer2.prototype.op_2_3_list = '-> != && || ++ -- << >> == <= >= += -= *= /= %= &= |= ^= ...  <<= >>='.split(/\s+/);

Tokenizer2.prototype.kw_list 
  = ('auto break case char const continue'
  + ' default do double else enum extern float for'
  + ' goto if int long register return short signed'
  + ' sizeof static struct switch typedef'
  + ' union unsigned void volatile while').split(/\s+/);

// それ以外
// EOF IDENTIFIER STRING_LITERAL CONSTANT TYPE_NAME
//     \w[\w\d]*  "..."     '?'  \d+ 0x 010 1.0F 3. .5 .5e+3
//     EXTERN_STM STM_DEF
//  cut \s+ #aaa...$ /*...*/   //...$
//  split first ... \x0d\x0a



Tokenizer2.prototype.read_next_token = function() {
    while(true)
    {
        let rest_length = this.str_rest.length;
        this.str_rest = this.str_rest.replace(/^[\s\n\r\x0a\x0d]+/s, '');
        this.str_rest = this.str_rest.replace(/^\/\/[^\n]*(\x0d\x0a|\x0a|\r\n|\n|$)/s, '');
        this.str_rest = this.str_rest.replace(/^\/\*([^\*]|\*[^\/])*\*\//s, '');
        this.str_rest = this.str_rest.replace(/^\#\w[^\n]*(\x0d\x0a|\x0a|\r\n|\n|$)/s, '');
        if (rest_length == this.str_rest.length) { break; }
    }


    if (this.str_rest.length == 0)
    {
        const eof_pos = this.str_orig.length;
        if (this.following_token_id == 'EOF' || this.following_token_id == '(eot)' )
        {
            this.following_token_id = '(eot)';
            this.following_token_sv = null;
            return;
        }
        else
        {
            this.following_token_id = 'EOF';
            this.following_token_sv = {id: 'EOF', val: null, is_terminal: 1, start: eof_pos, end: eof_pos};
            return;
        }
    }

    let s = this.str_rest;
    const token_start = this.str_orig.length - s.length;
    let id, val;

    let m = new TokenMacher();

    if (m.str_list(s, this.op_1_list)) { id = m.match; val = id.slice(); }
    else if (m.str_list(s, this.op_2_3_list )) { id = this.op_2_3_name[m.match]; val = m.match.slice(); }
    else if (m.str_list(s, this.kw_list )) { id = m.match.toUpperCase(); val = m.match.slice(); }
    else if (m.regexp(s, /^\"[^\"]*\"/)) { id = 'CONSTANT'; val = m.match.slice(); }
    else if (m.regexp(s, /^\d+/)) { id = 'CONSTANT'; val = m.match.slice(); }
    else if (m.regexp(s, /^\w[\w\d]*/)) { id = 'IDENTIFIER'; val = m.match.slice(); }

    // else if (m.regexp(s, /^[\>\(\)]/s)) { id = m.match; val = id.slice(); }
    // else if (m.regexp(s, /^[^\>\(\)\s]+/s)) { id = 't_Node'; val = m.match; }
    else {throw Error(`Lex Error! rest = '${s}'\n`);}

    this.str_rest = m.rest;
    const token_end = this.str_orig.length - this.str_rest.length;

    this.following_token_id = id;
    this.following_token_sv = {id: id, val: val, is_terminal: 1, start: token_start, end: token_end};
};

///////////////////////////////////////////////////////////////





var Tokenizer = function(token_list)
{
    //////
    this.token_list= [... token_list]; // clone array
    this.pos= 0;
    this.read_next_token();


    this.hoge = '(xabc)';
};

Tokenizer.prototype.reset = function() { this.pos =0; this.read_next_token(); };

Tokenizer.prototype.read_next_token = function() {
    if (this.pos >= this.token_list.length)
    {
        this.following_token_id = '(eot)';
        this.following_token_sv = null;
        return;
    }



    let s = this.token_list[this.pos];
    this.pos ++;

    let val = s;
    if ( String(val).match(/^\d+$/) ) { s = 'i'; }

    this.following_token_id = s;
    this.following_token_sv = {id:s, val: val, is_terminal: 1};
};




